166	// jsonTokenName describes a token the way the structural error messages do.
167	func jsonTokenName(tok json.Token) string {
168		switch t := tok.(type) {
169		case json.Delim:
170			switch t {
171			case '[':
172				return "array"
173			case '{':
174				return "object"
175			case ']':
176				return "extra closing bracket ']'"
177			case '}':
178				return "extra closing brace '}'"
179			}
180		case nil:
181			return "null"
182		case bool:
183			return "boolean"
184		case string:
185			return "string"
186		case json.Number:
187			return "number"
188		case float64:
189			return "number"
190		case int64:
191			return "number"
192		}
193		return "value"
194	}
195	
196	// trailingTokenName identifies the kind of JSON token started by the first
197	// non-whitespace byte after a closed object.
198	func trailingTokenName(b byte) string {
199		switch b {
200		case '{':
201			return "object"
202		case '[':
203			return "array"
204		case '}':
205			return "extra closing brace '}'"
206		case ']':
207			return "extra closing bracket ']'"
208		case '"':
209			return "string"
210		case 't', 'f':
211			return "boolean"
212		case 'n':
213			return "null"
214		default:
215			if (b >= '0' && b <= '9') || b == '-' {
216				return "number"
217			}
218			return fmt.Sprintf("unexpected character %q", rune(b))
219		}
220	}
221	
222	// fieldTable maps the case-insensitive spellings of a struct object's
223	// JSON fields to their canonical names.
224	func fieldTable(fields ...string) map[string]string {
225		table := make(map[string]string, len(fields))
226		for _, f := range fields {
227			table[strings.ToLower(f)] = f
228		}
229		return table
230	}
231	
232	// nestedObjectSpec pairs a nested object's field table with the label used
233	// in its duplicate-field errors.
234	type nestedObjectSpec struct {
235		fields map[string]string
236		label  string
237	}
