// jsonTokenName describes a token the way the structural error messages do.
func jsonTokenName(tok json.Token) string {
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '[':
			return "array"
		case '{':
			return "object"
		case ']':
			return "extra closing bracket ']'"
		case '}':
			return "extra closing brace '}'"
		}
	case nil:
		return "null"
	case bool:
		return "boolean"
	case string:
		return "string"
	case json.Number:
		return "number"
	case float64:
		return "number"
	case int64:
		return "number"
	}
	return "value"
