354	// records. Detection is not re-run: the archived finding, evidence and rule
355	// version are reused. A finding at least minSeverity is processed; findings
356	// below the threshold leave no record, so lowering the threshold later can
357	// still produce them. Every already-processed identity is skipped, which
358	// makes repeated imports, repeated generation, wider or overlapping ranges,
359	// version switches and restarts idempotent. Channels are independent, and
360	// blocks at the same height with different hashes are handled separately.
361	//
362	// All new records of one call are committed together or not at all. The
363	// returned slice contains only records created by this call (alerts and
364	// suppressions distinguished), sorted by height, block hash, tx hash and
365	// kind; an empty result serializes as [].
366	func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
367		if strings.TrimSpace(chainID) == "" {
368			return nil, errors.New("chainId must be a non-empty string")
369		}
370		if strings.TrimSpace(channel) == "" {
371			return nil, errors.New("channel must be a non-empty name")
372		}
373		if err := ValidateSeverity(minSeverity); err != nil {
374			return nil, err
375		}
376		if startHeight > endHeight {
377			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
378		}
379		if err := os.MkdirAll(dir, 0o755); err != nil {
380			return nil, err
381		}
382		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
383		if err != nil {
384			return nil, err
385		}
386		defer lock.Close()
387	
388		data, err := readArchive(dir)
389		if err != nil {
390			return nil, err
391		}
392		processed := make(map[alertKey]struct{}, len(data.AlertRecords))
393		for _, r := range data.AlertRecords {
394			processed[r.identity()] = struct{}{}
395		}
396	
397		created := []ProcessingRecord{}
398		for _, rec := range data.Records {
399			if rec.ChainID != chainID {
400				continue
401			}
402			height := uint64(rec.BlockNumber)
403			if height < startHeight || height > endHeight {
404				continue
405			}
406			version := rec.ruleVersion()
407			for _, f := range rec.Findings {
408				if f.Severity < minSeverity {
409					// Below the threshold: no record is written, so the event
410					// stays eligible after a later threshold reduction.
411					continue
412				}
413				key := alertKey{
414					chainID:   rec.ChainID,
415					blockHash: rec.BlockHash,
416					txHash:    f.TxHash,
417					kind:      f.Kind,
418					channel:   channel,
419				}
420				if _, ok := processed[key]; ok {
421					continue
422				}
423				pool, ok := victimPool(f)
424				if !ok {
425					return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
426						rec.ChainID, rec.BlockHash, f.TxHash)
427				}
428				hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
429				status := AlertStatusAlert
430				if len(hits) > 0 {
431					status = AlertStatusSuppressed
432				}
433				record := ProcessingRecord{
434					ChainID:      rec.ChainID,
435					BlockHash:    rec.BlockHash,
436					BlockNumber:  height,
437					Pool:         pool,
438					Channel:      channel,
439					Finding:      f,
440					Version:      version,
441					MinSeverity:  minSeverity,
442					Status:       status,
443					Suppressions: hits,
444				}
445				created = append(created, record)
446				processed[key] = struct{}{}
447			}
448		}
449		sortRecords(created)
450		if len(created) > 0 {
451			data.AlertRecords = append(data.AlertRecords, created...)
452			if err := writeArchiveAtomic(dir, data); err != nil {
453				return nil, err
454			}
455		}
456		return created, nil
457	}
458	
459	// AlertHistory returns stored processing records on chainID for channel in
460	// the inclusive range [startHeight, endHeight]. It only reads the archive;
461	// suppressions registered afterwards cannot alter the stored content.
462	func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
463		if strings.TrimSpace(chainID) == "" {
464			return nil, errors.New("chainId must be a non-empty string")
465		}
466		if strings.TrimSpace(channel) == "" {
467			return nil, errors.New("channel must be a non-empty name")
468		}
469		if startHeight > endHeight {
470			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
471		}
472		if _, serr := os.Stat(dir); serr != nil {
473			if errors.Is(serr, os.ErrNotExist) {
474				return []ProcessingRecord{}, nil
475			}
476			return nil, serr
477		}
478		lock, err := lockArchive(dir, syscall.LOCK_SH)
479		if err != nil {
480			return nil, err
481		}
482		defer lock.Close()
483	
484		data, err := readArchive(dir)
485		if err != nil {
486			return nil, err
487		}
488		out := []ProcessingRecord{}
489		for _, r := range data.AlertRecords {
490			if r.ChainID != chainID || r.Channel != channel {
491				continue
492			}
493			if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
494				continue
495			}
496			out = append(out, r)
497		}
498		sortRecords(out)
499		return out, nil
500	}
501	
502	// RegisterSuppression validates raw and stores one suppression condition in
503	// the archive. Re-registering the same ID with identical content succeeds
504	// without adding anything (created is false) — this stays true after the
505	// condition was revoked and never re-enables it; the same ID with different
506	// content is rejected. New conditions only affect conclusions that have not
507	// been processed yet: historical alerts are never rewritten as suppressed,
508	// and suppressed records are not re-alerted when a condition's range ends.
509	// The registration document cannot set revoked state.
510	func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
511		s, err = ParseSuppression(raw)
512		if err != nil {
513			return Suppression{}, false, err
514		}
515		if err := os.MkdirAll(dir, 0o755); err != nil {
516			return Suppression{}, false, err
517		}
518		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
519		if lerr != nil {
520			return Suppression{}, false, lerr
521		}
522		defer lock.Close()
523	
524		data, err := readArchive(dir)
525		if err != nil {
526			return Suppression{}, false, err
527		}
528		for _, existing := range data.Suppressions {
529			if existing.ID == s.ID {
530				if suppressionEqual(existing, s) {
531					return existing, false, nil
532				}
533				return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
534			}
535		}
536		data.Suppressions = append(data.Suppressions, s)
537		if err := writeArchiveAtomic(dir, data); err != nil {
538			return Suppression{}, false, err
539		}
540		return s, true, nil
541	}
542	
543	// RevokeSuppression withdraws the condition with the given exact ID. The
544	// first successful revocation returns changed=true and the full condition
545	// with Revoked set; revoking the same ID again succeeds with changed=false.
546	// A blank ID is rejected, and an ID that was never registered — including
547	// any ID in an empty archive — returns ErrUnknownSuppression. The revoked
548	// condition is retained (still listed) but stops matching conclusions
549	// processed from now on; it cannot be revived, a fresh ID is required to
550	// suppress again.
551	//
552	// The revocation is committed atomically under the archive lock: a busy
553	// archive, a corrupted one or a failed save leaves every condition, report
554	// and processing record untouched. One generation run always sees either
555	// the pre- or the post-revocation condition set in full.
556	func RevokeSuppression(dir, id string) (s Suppression, changed bool, err error) {
557		if strings.TrimSpace(id) == "" {
558			return Suppression{}, false, errors.New("suppression id must be a non-empty string")
559		}
560		if err := os.MkdirAll(dir, 0o755); err != nil {
561			return Suppression{}, false, err
562		}
563		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
564		if lerr != nil {
565			return Suppression{}, false, lerr
566		}
567		defer lock.Close()
568	
569		data, err := readArchive(dir)
570		if err != nil {
571			return Suppression{}, false, err
572		}
573		for i := range data.Suppressions {
574			if data.Suppressions[i].ID != id {
575				continue
576			}
577			if data.Suppressions[i].Revoked {
578				return data.Suppressions[i], false, nil
579			}
580			data.Suppressions[i].Revoked = true
581			if err := writeArchiveAtomic(dir, data); err != nil {
582				return Suppression{}, false, err
583			}
584			return data.Suppressions[i], true, nil
585		}
586		return Suppression{}, false, fmt.Errorf("%w: %s", ErrUnknownSuppression, id)
587	}
588	
589	// ListSuppressions returns every suppression condition stored in the
590	// archive, ordered by ID. A read on an absent archive returns an empty list.
591	func ListSuppressions(dir string) ([]Suppression, error) {
592		if _, serr := os.Stat(dir); serr != nil {
593			if errors.Is(serr, os.ErrNotExist) {
594				return []Suppression{}, nil
595			}
596			return nil, serr
597		}
598		lock, err := lockArchive(dir, syscall.LOCK_SH)
599		if err != nil {
600			return nil, err
601		}
602		defer lock.Close()
603	
604		data, err := readArchive(dir)
605		if err != nil {
606			return nil, err
607		}
608		out := append([]Suppression(nil), data.Suppressions...)
609		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
610		if out == nil {
611			out = []Suppression{}
612		}
613		return out, nil
614	}
